import re, os

bib_path = '/home/ubuntu/.agent-ml-research-idea_gen_0514_3/projects/gen-depth-fingerprint/artifacts/_project/paper/references.bib'
tex_dir = '/home/ubuntu/.agent-ml-research-idea_gen_0514_3/projects/gen-depth-fingerprint/artifacts/_project/paper/'

with open(bib_path) as f:
    bib_content = f.read()
bib_keys = set(re.findall(r'@\w+\{(\w+),', bib_content))

cited = set()
for fname in os.listdir(tex_dir):
    if fname.endswith('.tex'):
        with open(os.path.join(tex_dir, fname)) as f:
            content = f.read()
        for match in re.findall(r'\\cite[tp]?\{([^}]+)\}', content):
            for key in match.split(','):
                cited.add(key.strip())

orphans = bib_keys - cited
print(f'Bib: {len(bib_keys)}, Cited: {len(cited)}, Orphans: {len(orphans)}')
if orphans:
    for k in sorted(orphans):
        print(f'  - {k}')
else:
    print('  (none)')
PYEOF
